-- Frank Fletcher (profileID=6) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Frank Fletcher phrasings

SELECT p.argumentID, p.phrasingID, 6, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 6
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 6 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=6 AND targArgID IN (100,101,107,108,118,123,134,135,136,140,155,165,192,197,199,201,226,227,228,229,264,265,266,267,275,288,291,297,321,322,328,400,401,404,412,414,450,460,476,494,495,527,528,529,530,560,561,601,607,609,611,612,616,727,745,895,910,911,920,1045,1095,1096,1159,1160,1172,1179,1181,1229,1278,1345,1346,1410,1589,1591,1597,1602);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 6
SET pe.active = o.acceptance
WHERE pe.profileID = 6;

SELECT 'Done: endorsements for profileID=6' AS status;